-- 创建 chapters（章）表
CREATE TABLE chapters (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
  title VARCHAR(255) NOT NULL,
  sort_order INTEGER DEFAULT 0,
  is_published BOOLEAN DEFAULT true,
  created_at TIMESTAMP DEFAULT NOW(),
  updated_at TIMESTAMP DEFAULT NOW()
);

-- 创建 sections（节）表
CREATE TABLE sections (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  chapter_id UUID NOT NULL REFERENCES chapters(id) ON DELETE CASCADE,
  title VARCHAR(255) NOT NULL,
  content TEXT,
  sort_order INTEGER DEFAULT 0,
  is_published BOOLEAN DEFAULT true,
  created_at TIMESTAMP DEFAULT NOW(),
  updated_at TIMESTAMP DEFAULT NOW()
);

-- 创建索引
CREATE INDEX idx_chapters_course_id ON chapters(course_id);
CREATE INDEX idx_chapters_sort_order ON chapters(sort_order);
CREATE INDEX idx_sections_chapter_id ON sections(chapter_id);
CREATE INDEX idx_sections_sort_order ON sections(sort_order);

-- 迁移旧数据：将 course_chapters 数据迁移到 chapters 表
INSERT INTO chapters (id, course_id, title, sort_order, is_published, created_at, updated_at)
SELECT id, course_id, title, sort_order, is_published, created_at, updated_at
FROM course_chapters;

-- 为每个 chapter 创建一个默认 section，将 content 迁移过去
INSERT INTO sections (chapter_id, title, content, sort_order, is_published, created_at, updated_at)
SELECT 
  id as chapter_id,
  '默认节' as title,
  content,
  0 as sort_order,
  is_published,
  created_at,
  updated_at
FROM course_chapters
WHERE content IS NOT NULL AND content != '';

